import json,re,os
from pathlib import Path
out=Path(os.environ['OUT']); image=Path('inputs/chall/Carmine-Falcone.raw')
anchors=[1101107200,2244853760];terms=['unpad','padTo','randomBytes','padBuffer','padding','readUInt32BE','seed.seco','setSecoPassphrase','getSecoPassphrase','serialize','deserialize','entropy']
summary=[];contexts=[];runs=[]
with image.open('rb') as f:
 for a in anchors:
  start=a-262144;f.seek(start);b=f.read(2097152);(out/f'window-{a}.bin').write_bytes(b)
  row={'anchor':a,'start':start,'bytes':len(b),'counts':{}}
  for term in terms:
   row['counts'][term]={}
   for encoding in ['ascii','utf-16le']:
    needle=term.encode(encoding);positions=[m.start() for m in re.finditer(re.escape(needle),b,re.I)];row['counts'][term][encoding]=len(positions)
    for pos in positions:
     context=b[max(0,pos-256):min(len(b),pos+len(needle)+768)]
     contexts.append({'anchor':a,'physical_offset':start+pos,'term':term,'encoding':encoding,'context':context.decode(encoding,errors='replace')})
  for m in re.finditer(rb'[\x20-\x7e\t\r\n]{80,}',b):
   runs.append({'physical_offset':start+m.start(),'length':len(m.group()),'text':m.group().decode('ascii')})
  summary.append(row)
(out/'source-contexts.json').write_text(json.dumps(contexts,indent=2));(out/'source-ascii-runs.jsonl').write_text(''.join(json.dumps(x)+'\n' for x in runs));(out/'window-summary.json').write_text(json.dumps(summary,indent=2));print(json.dumps({'windows':summary,'context_records':len(contexts),'long_ascii_runs':len(runs)},sort_keys=True))
